function par = nk_log_tp_coef(z,d,m,x,par)
% Eva F. Janssens and Sean McCrary
% "Efficient Estimation of Nonlinear DSGE Models"

% Policy function parameters
x  = x(:);
a0 = x(1); a1 = x(2); a2 = x(3); a3 = x(4);  % Inflation
b0 = x(5); b1 = x(6); b2 = x(7); b3 = x(8);  % Labor

% Model parameters
% PE(kp,n,t,b0,b1,b2,b3,z,d,m,a0,a1,a2,a3,rd,rm,rz,df,sz,sd,sm)
% EE(rd,sd,d,rz,sz,z,rm,sm,m,t,a0,a1,a2,a3,b0,b1,b2,b3,tp,ty)
rz    = par.rho_z;
sz    = par.sig_z;
rd    = par.rho_d;
sd    = par.sig_d;
rm    = par.rho_m;
sm    = par.sig_m;
ty    = par.phi_y;
tp    = par.phi_pi;
t     = par.tau;
n     = par.eta;
df    = par.beta;
kp    = par.kappa; % Log-linear Philips Curve Term

%-------------------------------------------------------------------------%
%  Residuals: 8 equations in 8 unknowns
F = zeros(8,1);

% Euler equation
F(1) = -a0 - a1*rz*z - a2*d*rd - a3*m*rm + d*(rd - 1) + m + sd^2*(-a2 - b2*t + 1)^2/2 + sm^2*(a3 + b3*t)^2/2 + sz^2*(a1 + t*(b1 + 1))^2/2 + t*z*(1 - rz) + t*(b1*z*(1 - rz) + b2*d*(1 - rd) + b3*m*(1 - rm)) + tp*(a0 + a1*z + a2*d + a3*m) + ty*(b0 + b1*z + b2*d + b3*m + z);

% Euler equation: dz
F(2) = a1*tp - a1*rz + ty*(b1 + 1) - t*(rz - 1) - b1*t*(rz - 1);

% Euler equation: dd
F(3) = rd - a2*rd + a2*tp + b2*ty - b2*t*(rd - 1) - 1;

% Euler equation: dm
F(4) = a3*tp - a3*rm + b3*ty - b3*t*(rm - 1) + 1;

% Pricing equation
F(5) = -df*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) - kp*(1 - exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m))) + exp(a0 + a1*z + a2*d + a3*m) - exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m);

% Pricing equation: dz
F(6) = a1*exp(a0 + a1*z + a2*d + a3*m) - 2*a1*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m) - df*(a1*rz + (1 - t)*(b1*(rz - 1) + rz - 1))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*(2*a1*rz + (1 - t)*(b1*(rz - 1) + rz - 1))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + kp*(b1*(n + t) + t - 1)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m));

% pricing equation: dd
F(7) = a2*exp(a0 + a1*z + a2*d + a3*m) - 2*a2*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m) + b2*kp*(n + t)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m)) - df*(a2*rd + b2*(1 - t)*(rd - 1) + rd - 1)*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*(2*a2*rd + b2*(1 - t)*(rd - 1) + rd - 1)*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)));

% pricing equation: dm
F(8) = a3*exp(a0 + a1*z + a2*d + a3*m) - 2*a3*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m) + b3*kp*(n + t)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m)) - df*(a3*rm + b3*(1 - t)*(rm - 1))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*(2*a3*rm + b3*(1 - t)*(rm - 1))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)));

%----------------------------------------------------------------------------------------------------------------
%   Jacobian
J = zeros(8,8);

% Euler
J(1,1) = tp-1;
J(1,2) = (a1 + t*(b1 + 1))*sz^2 - rz*z + tp*z;
J(1,3) = (a2 + b2*t - 1)*sd^2   - d*rd + d*tp;
J(1,4) = -m*rm + m*tp + sm^2*(2*a3 + 2*b3*t)/2;
J(1,5) = ty;
J(1,6) = t*(a1 + t*(b1 + 1))*sz^2 + ty*z - t*z*(rz - 1);
J(1,7) = t*(a2 + b2*t - 1)*sd^2 + d*ty - d*t*(rd - 1);
J(1,8) = m*t*(1 - rm) + m*ty + sm^2*t*(a3 + b3*t);

% Euler: dz
%J(2,1) = 0;
J(2,2) = tp-rz;
%J(2,3) = 0;
%J(2,4) = 0;
%J(2,5) = 0;
J(2,6) = ty - t*(rz - 1);
%J(2,7) = 0;
%J(2,8) = 0;

% Euler: dd
%J(3,1) = 0;
%J(3,2) = 0;
J(3,3) = tp-rd;
%J(3,4) = 0;
%J(3,5) = 0;
%J(3,6) = 0;
J(3,7) = ty - t*(rd - 1);
%J(3,8) = 0;

% Euler: dm
%J(4,1) = 0;
%J(4,2) = 0;
%J(4,3) = 0;
J(4,4) = tp-rm;
%J(4,5) = 0;
%J(4,6) = 0;
%J(4,7) = 0;
J(4,8) = ty - t*(rm - 1);

% Price
J(5,1) = -df*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + 2*df*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + exp(a0 + a1*z + a2*d + a3*m) - 2*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m);
J(5,2) = -df*rz*z*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + 2*df*rz*z*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) - df*sz^2*(2*a1 + 2*(1 - t)*(b1 + 1))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + df*sz^2*(8*a1 + 4*(1 - t)*(b1 + 1))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + z*exp(a0 + a1*z + a2*d + a3*m) - 2*z*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m);
J(5,3) = -d*df*rd*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + 2*d*df*rd*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + d*exp(a0 + a1*z + a2*d + a3*m) - 2*d*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m) - df*sd^2*(2*a2 + 2*b2*(1 - t) + 2)*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + df*sd^2*(8*a2 + 4*b2*(1 - t) + 4)*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2;
J(5,4) = -df*m*rm*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + 2*df*m*rm*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) - df*sm^2*(2*a3 + 2*b3*(1 - t))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + df*sm^2*(8*a3 + 4*b3*(1 - t))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + m*exp(a0 + a1*z + a2*d + a3*m) - 2*m*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m);
J(5,5) = kp*exp(z*(t - 1) + (n + t)*(b0 + b2*d + b3*m + b1*z))*(n + t);
J(5,6) = -df*sz^2*(2 - 2*t)*(a1 + (1 - t)*(b1 + 1))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + df*sz^2*(2 - 2*t)*(2*a1 + (1 - t)*(b1 + 1))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 - df*z*(1 - t)*(rz - 1)*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*z*(1 - t)*(rz - 1)*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + kp*z*(n + t)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m));
J(5,7) = -d*df*(1 - t)*(rd - 1)*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + d*df*(1 - t)*(rd - 1)*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + d*kp*(n + t)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m)) - df*sd^2*(2 - 2*t)*(a2 + b2*(1 - t) + 1)*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + df*sd^2*(2 - 2*t)*(2*a2 + b2*(1 - t) + 1)*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2;
J(5,8) = -df*m*(1 - t)*(rm - 1)*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*m*(1 - t)*(rm - 1)*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) - df*sm^2*(2 - 2*t)*(a3 + b3*(1 - t))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + df*sm^2*(2 - 2*t)*(2*a3 + b3*(1 - t))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + kp*m*(n + t)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m));

