%---------------------------------------------------------------------------------------------------
% Newton solver
tol1    = 1;
tol2    = 1;
maxiter = 100;
crit    = 1e-8;
tol     = max(tol1,tol2);
B       = x;
count   = 0;

while tol > crit && count<maxiter

    % Newton solver
    Bp = B - J\F;

    % check convergence
    count = count +1;
    tol1  = norm(F);
    tol2  = norm(abs(Bp-B));
    tol   = max(tol1,tol2);

    % update coefficients
    B  = Bp;
    a0 = B(1); a1 = B(2); a2 = B(3); a3 = B(4);  % Inflation
    b0 = B(5); b1 = B(6); b2 = B(7); b3 = B(8);  % Labor

    %-----------------------------------------------------------------------------
    % update residuals

    % Euler equation
    F(1) = -a0 - a1*rz*z - a2*d*rd - a3*m*rm + d*(rd - 1) + m + sd^2*(-a2 - b2*t + 1)^2/2 + sm^2*(a3 + b3*t)^2/2 + sz^2*(a1 + t*(b1 + 1))^2/2 + t*z*(1 - rz) + t*(b1*z*(1 - rz) + b2*d*(1 - rd) + b3*m*(1 - rm)) + tp*(a0 + a1*z + a2*d + a3*m) + ty*(b0 + b1*z + b2*d + b3*m + z);

    % Euler equation: dz
    F(2) = a1*tp - a1*rz + ty*(b1 + 1) - t*(rz - 1) - b1*t*(rz - 1);

    % Euler equation: dd
    F(3) = rd - a2*rd + a2*tp + b2*ty - b2*t*(rd - 1) - 1;

    % Euler equation: dm
    F(4) = a3*tp - a3*rm + b3*ty - b3*t*(rm - 1) + 1;

    % Pricing equation
    F(5) = -df*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) - kp*(1 - exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m))) + exp(a0 + a1*z + a2*d + a3*m) - exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m);

    % Pricing equation: dz
    F(6) = a1*exp(a0 + a1*z + a2*d + a3*m) - 2*a1*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m) - df*(a1*rz + (1 - t)*(b1*(rz - 1) + rz - 1))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*(2*a1*rz + (1 - t)*(b1*(rz - 1) + rz - 1))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + kp*(b1*(n + t) + t - 1)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m));

    % pricing equation: dd
    F(7) = a2*exp(a0 + a1*z + a2*d + a3*m) - 2*a2*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m) + b2*kp*(n + t)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m)) - df*(a2*rd + b2*(1 - t)*(rd - 1) + rd - 1)*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*(2*a2*rd + b2*(1 - t)*(rd - 1) + rd - 1)*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)));

    % pricing equation: dm
    F(8) = a3*exp(a0 + a1*z + a2*d + a3*m) - 2*a3*exp(2*a0 + 2*a1*z + 2*a2*d + 2*a3*m) + b3*kp*(n + t)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m)) - df*(a3*rm + b3*(1 - t)*(rm - 1))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*(2*a3*rm + b3*(1 - t)*(rm - 1))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)));

    %------------------------------------------------------------------------------------
    % update jacobian

    % Euler
    %J(1,1) = tp-1;
    J(1,2) = (a1 + t*(b1 + 1))*sz^2 - rz*z + tp*z;
