    J(8,8) = b3*kp*m*(n + t)^2*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m)) - df*m*(1 - t)*(rm - 1)*(a3*rm + b3*(1 - t)*(rm - 1))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*m*(1 - t)*(rm - 1)*(2*a3*rm + b3*(1 - t)*(rm - 1))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) - df*sm^2*(2 - 2*t)*(a3 + b3*(1 - t))*(a3*rm + b3*(1 - t)*(rm - 1))*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 + df*sm^2*(2 - 2*t)*(2*a3 + b3*(1 - t))*(2*a3*rm + b3*(1 - t)*(rm - 1))*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1)))/2 - df*(1 - t)*(rm - 1)*exp(sd^2*(a2 + b2*(1 - t) + 1)^2/2 + sm^2*(a3 + b3*(1 - t))^2/2 + sz^2*(a1 + (1 - t)*(b1 + 1))^2/2)*exp(a0 + a1*rz*z + a2*d*rd + a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + df*(1 - t)*(rm - 1)*exp(sd^2*(2*a2 + b2*(1 - t) + 1)^2/2 + sm^2*(2*a3 + b3*(1 - t))^2/2 + sz^2*(2*a1 + (1 - t)*(b1 + 1))^2/2)*exp(2*a0 + 2*a1*rz*z + 2*a2*d*rd + 2*a3*m*rm + d*(rd - 1) + (1 - t)*(b1*z*(rz - 1) + b2*d*(rd - 1) + b3*m*(rm - 1) + z*(rz - 1))) + kp*(n + t)*exp(z*(t - 1) + (n + t)*(b0 + b1*z + b2*d + b3*m));

end

%fprintf('Count %4.2f \n', count);

% Output
if ~isreal(B) || ~isreal(F) || any(~isfinite(B)) || ...
        any(~isfinite(F)) || tol > crit || norm(F) > crit
    error('SimpleNK:TPNewton', ...
        'TP Newton did not converge at state [%g %g %g]; residual %.3e.', ...
        z,d,m,norm(F));
end
par = B;
end
